end

function FightBonusCellNode:Refresh(data, ind, levelId, type)
    if not data then
        return
    end
    self._data = data
    self._ind = checkNumber(ind)
    self._levelId = levelId
    self._curLevelType = GoodsUtils.GetIdType(self._levelId, Constants.IDArea.Quests)     --关卡类型
    self._curType = checkNumber(type)

    print(RewardType[self._curType])
    CfUtils.FillText(self.name, RewardType[self._curType])
    KTool.SetActive(self.controller.gameObject, true)

    self:FillRewardData()
end

function FightBonusCellNode:FillRewardData()
    for i = 1, #self._data do
        local reward = self._data[i]
        if checkNumber(reward.id) ~= 0 then
            local itemGo = CfUtils.InstantiateGo(self.item, self.items)
            if itemGo then
                local scr = CfUtils.GetLuaScr(itemGo, UIFightRewardNode)
                if scr then
                    local go = scr:RefreshNormal(reward, 0.65)

                    local isGet = false
                    --三星
                    if self._curType == Constants.QuestRewardType.StarRewardId then
                        isGet = QuestConfMgr:GetInstance():IsCompleteAllCondition(self._levelId)
                    --首通
                    elseif self._curType == Constants.QuestRewardType.FristRewards then
                        --if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                        --    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                        --    isGet = equipQuestComp:IsPassQuestById(equipQuestComp:GetCurSeniorQuestId())
                        --else
                            isGet = QuestConfMgr:GetInstance():IsPassQuest(self._levelId)
                        --end
                    end

                    scr = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
                    if scr then
                        scr:SetSanXingGainShow(isGet)

                        local itemData = GoodsConfMgr:GetInstance():GetGoodsVoById(reward.id)
                        scr:SetClickCallback(function()
                            GameUtils.ShowCommonTipsBoard(go, itemData.name, itemData.desc, itemData.quality, itemData.id)
                        end)
                    end
                end
            end
        end
    end
    --CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.controller.gameObject.transform:GetComponent("RectTransform"))
end

function FightBonusCellNode:PlayAni(count)
    local ani = self.controller:GetComponent(typeof(Animation))
    self._co = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(count * 0.22))
        if ani then
            ani:Play("Ani_Canvas_Alpha")
            --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.22))
        end
        CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.controller.gameObject.transform.parent.transform:GetComponent("RectTransform"))
    end)
end

function FightBonusCellNode:OnDestroy()
    if not isNull(self) then
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return FightBonusCellNode
